head.b:skin:
/* 
THEME: Quotes Calendar (Earth Tone & Minimalist)
SYSTEM: 30-Day Content Planner
*/
:root {
    --warm-sand: #f5ebe0;
    --clay: #d5bdaf;
    --terracotta: #a98467;
    --deep-oak: #6c584c;
    --text-dark: #352f2a;
}
body {
    background-color: var(--warm-sand);
    color: var(--text-dark);
    font-family: 'Inter', 'Quicksand', sans-serif;
    margin: 0; padding: 0;
}
.header-wrap {
    background: linear-gradient(135deg, var(--terracotta), var(--deep-oak));
    color: #fff;
    padding: 60px 20px;
    text-align: center;
    border-bottom: 5px solid var(--clay);
}
.main-container {
    max-width: 800px;
    margin: -40px auto 60px;
    padding: 20px;
}
.quote-card {
    background: #ffffff;
    border-radius: 20px;
    box-shadow: 0 10px 30px rgba(108, 88, 76, 0.15);
    padding: 40px;
    margin-bottom: 25px;
    border: 1px solid var(--clay);
}
.input-group { margin-bottom: 25px; }
.input-group label {
    display: block;
    font-weight: 700;
    margin-bottom: 10px;
    color: var(--deep-oak);
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.input-group input, .input-group textarea {
    width: 100%;
    padding: 15px;
    border: 2px solid var(--warm-sand);
    border-radius: 12px;
    font-family: inherit;
    box-sizing: border-box;
    background: #fafafa;
    transition: 0.3s;
}
.input-group input:focus, .input-group textarea:focus {
    outline: none;
    border-color: var(--terracotta);
    background: #fff;
}
.input-group textarea { height: 110px; }

.lang-options { display: flex; gap: 30px; margin-top: 10px; }
.lang-item { display: flex; align-items: center; cursor: pointer; font-weight: 600; }
.lang-item input { width: auto; margin-right: 10px; accent-color: var(--terracotta); }

h2 { color: var(--terracotta); text-align: center; margin-top: 0; font-family: 'Playfair Display', serif; font-size: 28px; }

.copy-btn {
    background: var(--deep-oak);
    color: white;
    border: none;
    padding: 18px;
    cursor: pointer;
    font-weight: bold;
    width: 100%;
    border-radius: 12px;
    transition: 0.4s;
    font-size: 16px;
    text-transform: uppercase;
    letter-spacing: 2px;
}
.copy-btn:hover { background: var(--terracotta); transform: translateY(-3px); box-shadow: 0 5px 15px rgba(169, 132, 103, 0.4); }
footer { text-align: center; color: var(--terracotta); padding: 30px; font-size: 13px; font-style: italic; }

body.script:
function copyPrompt() {
    var title = document.getElementById("inputTitle").value || "Life & Wisdom";
    var notes = document.getElementById("inputNotes").value || "Mix of different daily vibes.";

    var selectedLang = document.querySelector('input[name="lang"]:checked').value;
    var template = (selectedLang === 'id') ? 
                   document.getElementById("templateID").innerText : 
                   document.getElementById("templateEN").innerText;

    var finalPrompt = template.replace("[USER_TITLE]", title).replace("[USER_NOTES]", notes);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("✨ 30-Day Quotes Prompt (" + (selectedLang === 'id' ? 'Indonesia' : 'English') + ") copied! Your content is ready for a month.");
}
